package com.smarthub.plus;
import android.content.*;import android.content.res.ColorStateList;import android.os.*;import android.view.*;import android.widget.*;import java.util.*;import java.util.concurrent.*;
/** Independent, live Tuner/0003 display. Unsupported metrics remain unavailable. */
public final class SignalInformationActivity extends HubActivity {
 private final Handler main=new Handler(Looper.getMainLooper());private final ExecutorService io=Executors.newSingleThreadExecutor();private DirectReceiverSignal reader;private TextView channel,source,strengthValue,qualityValue,metrics,rf,format,details;private ProgressBar strength,quality;private LinearLayout panel;private SignalProgrammeCards programmeCards;private boolean closed;private ReceiverCatalog.Channel selected;
 private final Runnable tick=new Runnable(){public void run(){if(closed||reader==null)return;SatelliteState s=SatelliteState.read(SignalInformationActivity.this);reader.refresh(s);if(programmeCards!=null)programmeCards.refresh(s);ReceiverSignalReading frame=DirectReceiverSignal.reading(s);boolean owned=frame!=null&&frame.locked==1&&frame.tp==prefs().getInt("own_dvb_runtime_tp",-1)&&prefs().getInt("own_dvb_mapping_version",0)==3&&s.channelId.equals("DVB:"+prefs().getString("own_dvb_physical",""))&&prefs().getString("own_dvb_physical","").startsWith(prefs().getString("own_dvb_physical_tp","invalid")+":");channel.setText(owned?s.channelName:tx("الموالف الحالي","Active tuner"));source.setText(DirectReceiverSignal.sourceLabel(s,ar)+(frame==null?"":"  ·  Tuner "+frame.tuner));String sv=frame==null?"":frame.value("strength"),qv=frame==null?"":frame.value("quality");renderMeter(strength,strengthValue,sv);renderMeter(quality,qualityValue,qv);metrics.setText("SNR  "+(frame==null?"—":value(frame.value("snr")))+"      BER  "+(frame==null?"—":value(frame.value("ber")))+"      AGC  —");boolean have=owned&&selected!=null&&selected.physical().equals(prefs().getString("own_dvb_physical",""));rf.setText(have?selected.satName+" ("+ReceiverChannelRepository.orbital(selected.angle)+")\n"+selected.frequency+" MHz    "+selected.pol+"    "+selected.symbolRate+" kS/s":tx("التردد والقمر: غير متاحين بتطابق متحقق","Satellite and RF: no verified match"));String signal=frame!=null&&frame.locked==1?frame.format:"";String[] parts=signal.split(" +");String system=parts.length>0&&!signal.isEmpty()?parts[0]:"—",mod=parts.length>1?parts[1]:"—",fec=parts.length>2?parts[2]:"—";format.setText(system+"       "+mod+"       FEC "+fec);details.setText(tx("القياسات مباشرة من الموالف · تحديث كل ثانية\nAGC لا توفره واجهة الجهاز الحالية","Live tuner measurements · updates every second\nAGC is unavailable from this receiver interface"));main.postDelayed(this,1000);}};
 @Override public void onCreate(Bundle s){super.onCreate(s);LinearLayout body=col();body.setBackgroundColor(0xff000000);body.setPadding(dp(36),dp(22),dp(36),dp(22));panel=col();panel.setPadding(dp(28),dp(16),dp(28),dp(16));android.graphics.drawable.GradientDrawable bg=ReceiverPanelStyle.panel(this);try{bg.setStroke(dp(2),android.graphics.Color.parseColor(prefs().getString("signal_border","#FFDF78")));}catch(Exception ignored){}panel.setBackground(bg);body.addView(panel,new LinearLayout.LayoutParams(-1,-1));LinearLayout head=row();head.addView(text(tx("معلومات الإشارة","Signal Information"),28,true),new LinearLayout.LayoutParams(0,-2,1));Button colour=button(tx("لون الإطار","Border colour"));colour.setOnClickListener(v->ReceiverPanelStyle.choose(this,tx("لون الإطار","Border colour"),new String[]{tx("ذهبي","Gold"),tx("سماوي","Cyan"),tx("زمردي","Emerald")},0,i->{prefs().edit().putString("signal_border",new String[]{"#FFDF78","#39DCFF","#53D8B5"}[i]).apply();recreate();}));head.addView(colour);Button back=button(tx("رجوع","Back"));back.setOnClickListener(v->finish());head.addView(back);panel.addView(head);channel=text("",20,true);channel.setTextColor(ReceiverPanelStyle.GOLD);panel.addView(channel);source=text("",12,false);source.setTextColor(MUTED);panel.addView(source);strengthValue=large(tx("قوة الإشارة","Signal Strength"));strength=gauge();qualityValue=large(tx("جودة الإشارة","Signal Quality"));quality=gauge();metrics=text("",19,true);metrics.setGravity(Gravity.CENTER);metrics.setTextDirection(View.TEXT_DIRECTION_LTR);metrics.setPadding(0,dp(12),0,dp(12));panel.addView(metrics);rf=text("",19,true);rf.setTextDirection(View.TEXT_DIRECTION_LTR);rf.setGravity(Gravity.CENTER);panel.addView(rf);format=text("",19,true);format.setTextColor(ReceiverPanelStyle.CYAN);format.setTextDirection(View.TEXT_DIRECTION_LTR);format.setGravity(Gravity.CENTER);format.setPadding(0,dp(10),0,dp(8));panel.addView(format);details=text("",12,false);details.setTextColor(MUTED);details.setGravity(Gravity.CENTER);panel.addView(details);
 programmeCards=new SignalProgrammeCards(this,panel);
 setContentView(body);io.execute(()->{ReceiverCatalog.Channel c=ReceiverCatalog.get(this).channel(prefs().getLong("own_dvb_channel",-1));main.post(()->selected=c);});}
 private TextView large(String title){TextView t=text(title,23,true);t.setTag(title);t.setPadding(0,dp(10),0,dp(4));panel.addView(t);return t;}
 private ProgressBar gauge(){ProgressBar b=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);b.setMax(100);b.setProgressBackgroundTintList(ColorStateList.valueOf(0xff303039));panel.addView(b,new LinearLayout.LayoutParams(-1,dp(14)));return b;}
 private void renderMeter(ProgressBar bar,TextView label,String value){int n=0;try{n=Math.round(Float.parseFloat(value.replace("%","")));}catch(Exception ignored){}label.setText(label.getTag()+"     "+value(value));int color=n<35?0xfff15d67:n<65?0xffffcf65:0xff57e7a1;bar.setProgressTintList(ColorStateList.valueOf(color));bar.setProgress(n,true);bar.setAlpha(value.isEmpty()?.25f:1);}
 private static String value(String s){return s.isEmpty()?"—":s;}
 @Override protected void onResume(){super.onResume();if(programmeCards!=null)programmeCards.resume();reader=ReceiverInfoRepository.get(this).acquireSignal();main.post(tick);}
 @Override protected void onPause(){if(programmeCards!=null)programmeCards.pause();main.removeCallbacks(tick);if(reader!=null){ReceiverInfoRepository.get(this).releaseSignal(reader);reader=null;}super.onPause();}
 @Override protected void onDestroy(){closed=true;if(programmeCards!=null)programmeCards.close();main.removeCallbacksAndMessages(null);io.shutdownNow();super.onDestroy();}
}
